CREATE SCHEMA IF NOT EXISTS source;CREATE SCHEMA IF NOT EXISTS geo;CREATE SCHEMA IF NOT EXISTS legal;CREATE SCHEMA IF NOT EXISTS planning;CREATE SCHEMA IF NOT EXISTS evidence;
CREATE TABLE IF NOT EXISTS source.registry(id uuid PRIMARY KEY DEFAULT uuidv7(),code text NOT NULL UNIQUE,authority text NOT NULL,access_class text NOT NULL CHECK(access_class IN('A','B','C','D','F')),channel text,license_terms text,cadence text,secret_ref text,health text NOT NULL DEFAULT 'UNKNOWN',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source.snapshot(id uuid PRIMARY KEY DEFAULT uuidv7(),source_id uuid NOT NULL REFERENCES source.registry(id),source_date timestamptz,ingested_at timestamptz NOT NULL DEFAULT now(),parser_version text NOT NULL,sha256 text NOT NULL,object_key text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(source_id,sha256));
CREATE TABLE IF NOT EXISTS geo.parcel(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid,municipality_ibge text,source_snapshot_id uuid REFERENCES source.snapshot(id),official_identifier text,geom geometry(MultiPolygon,4326) NOT NULL,valid_from timestamptz,valid_to timestamptz,recorded_at timestamptz NOT NULL DEFAULT now(),superseded_at timestamptz);
CREATE INDEX IF NOT EXISTS geo_parcel_geom_gix ON geo.parcel USING gist(geom);
CREATE TABLE IF NOT EXISTS legal.document(id uuid PRIMARY KEY DEFAULT uuidv7(),municipality_ibge text,tenant_id uuid,kind text NOT NULL,title text NOT NULL,authority text,visibility text NOT NULL DEFAULT 'PUBLIC',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS legal.document_version(id uuid PRIMARY KEY DEFAULT uuidv7(),document_id uuid NOT NULL REFERENCES legal.document(id),source_snapshot_id uuid REFERENCES source.snapshot(id),version_label text,publication_date date,effective_date date,valid_from timestamptz,valid_to timestamptz,recorded_at timestamptz NOT NULL DEFAULT now(),superseded_at timestamptz,text_object_key text,sha256 text NOT NULL,status text NOT NULL DEFAULT 'DRAFT');
CREATE TABLE IF NOT EXISTS legal.rule(id uuid PRIMARY KEY DEFAULT uuidv7(),municipality_ibge text,zone_code text,parameter text NOT NULL,condition jsonb NOT NULL DEFAULT '{}'::jsonb,value_numeric numeric,value_text text,unit text,valid_from timestamptz,valid_to timestamptz,source_document_version_id uuid REFERENCES legal.document_version(id),source_locator text,status text NOT NULL DEFAULT 'CANDIDATE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS planning.zone(id uuid PRIMARY KEY DEFAULT uuidv7(),municipality_ibge text NOT NULL,code text NOT NULL,name text,geom geometry(MultiPolygon,4326) NOT NULL,source_snapshot_id uuid REFERENCES source.snapshot(id),valid_from timestamptz,valid_to timestamptz,UNIQUE(municipality_ibge,code,valid_from));CREATE INDEX IF NOT EXISTS planning_zone_geom_gix ON planning.zone USING gist(geom);
CREATE TABLE IF NOT EXISTS evidence.evidence(id uuid PRIMARY KEY DEFAULT uuidv7(),kind text NOT NULL,source_snapshot_id uuid REFERENCES source.snapshot(id),source_locator text,sha256 text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
